export const getDeleteUsersIdUrl = (id: string,) => {




  return `/users/${id}`
}

/**
 * Inactivates a user without deleting them: the user keeps appearing in the user list and as the author of their records. In the same transaction, all of their sessions and password recovery tokens are removed, so their next request is rejected and they can no longer sign in, refresh the session or recover the password. Records who inactivated the user in updated_by/updated_at. An admin cannot inactivate their own user, and the last active admin cannot be inactivated. The request has no body. Requires admin role.
 * @summary Inactivate user
 */
export const deleteUsersId = async (id: string, options?: Parameters<typeof customFetch>[1]): Promise<deleteUsersIdResponse> => {

  return customFetch<deleteUsersIdResponse>(getDeleteUsersIdUrl(id),
  {
    ...options,
    method: 'DELETE'


  }
);}





